-- pos-vehicle-fitment: Flyway baseline (flattened 2026-09-09 from the previous migration history) with the
-- ADR-0062 tenancy schema folded in. Generated by scripts/db/tenancy/flatten.py from a pg_dump of a
-- database migrated with the retired scripts; the tenancy additions are mechanical and are listed in
-- docs/TENANCY_SCHEMA.md. Global (unscoped) tables: src/main/resources/db/tenancy-global-tables.txt.
--
-- Tenant context: app_current_tenant() reads the session setting app.current_tenant, which the
-- TenantAwareDataSource (pos-tenancy-common, plan WS1) binds per checkout. Until then the owner role
-- carries a transitional default (postgres/init-tenancy.sh) and tests set it per connection.
-- With nothing bound: NULL -> every scoped table reads as empty and refuses inserts (fail closed).

-- Functions are emitted before the tables they reference (pg_dump order); do not validate bodies.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$;

CREATE TABLE public.fitment_tags (
    id uuid NOT NULL,
    tag_type character varying(255) NOT NULL,
    tag_value character varying(255) NOT NULL,
    hint_id uuid NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

CREATE TABLE public.make (
    id uuid NOT NULL,
    name character varying(255),
    manufacturer_id uuid,
    cache_timestamp timestamp without time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

CREATE TABLE public.manufacturer (
    id uuid NOT NULL,
    name character varying(255),
    cache_timestamp timestamp without time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

CREATE TABLE public.model (
    id uuid NOT NULL,
    name character varying(255),
    make_id uuid,
    cache_timestamp timestamp without time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

CREATE TABLE public.part_fitment_entity (
    id uuid NOT NULL,
    part_number_id bigint,
    vehicle_manufacturer_id uuid,
    vehicle_make_id uuid,
    vehicle_model_id uuid,
    vehicle_type_id uuid,
    vehicle_year character varying(255),
    engine_type character varying(255),
    submodel character varying(255),
    notes character varying(255),
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

CREATE TABLE public.part_fitment_entity_vehicle_variable_values (
    part_fitment_entity_id uuid NOT NULL,
    vehicle_variable_values_id uuid NOT NULL
);

CREATE TABLE public.vehicle_applicability_hints (
    hint_id uuid NOT NULL,
    product_id uuid NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    created_by character varying(255),
    updated_by character varying(255)
);

CREATE TABLE public.vehicle_type (
    id uuid NOT NULL,
    make_id uuid,
    vehicle_type_name character varying(255),
    vehicle_type_id character varying(255),
    cache_timestamp timestamp without time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

CREATE TABLE public.vehicle_variable (
    id uuid NOT NULL,
    name character varying(255),
    description character varying(255),
    cache_timestamp timestamp without time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

CREATE TABLE public.vehicle_variable_value (
    id uuid NOT NULL,
    variable_id uuid,
    variable_value character varying(255),
    value_id character varying(255),
    cache_timestamp timestamp without time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

ALTER TABLE ONLY public.fitment_tags
    ADD CONSTRAINT fitment_tags_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.make
    ADD CONSTRAINT make_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.manufacturer
    ADD CONSTRAINT manufacturer_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.model
    ADD CONSTRAINT model_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.part_fitment_entity
    ADD CONSTRAINT part_fitment_entity_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.vehicle_applicability_hints
    ADD CONSTRAINT vehicle_applicability_hints_pkey PRIMARY KEY (hint_id);

ALTER TABLE ONLY public.vehicle_type
    ADD CONSTRAINT vehicle_type_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.vehicle_variable
    ADD CONSTRAINT vehicle_variable_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.vehicle_variable_value
    ADD CONSTRAINT vehicle_variable_value_pkey PRIMARY KEY (id);

CREATE INDEX idx_fitment_tags_hint_id ON public.fitment_tags USING btree (hint_id);

CREATE INDEX idx_make_manufacturer_id ON public.make USING btree (manufacturer_id);

CREATE INDEX idx_model_make_id ON public.model USING btree (make_id);

CREATE INDEX idx_part_fitment_vehicle_values_fitment_id ON public.part_fitment_entity_vehicle_variable_values USING btree (part_fitment_entity_id);

CREATE INDEX idx_part_fitment_vehicle_values_value_id ON public.part_fitment_entity_vehicle_variable_values USING btree (vehicle_variable_values_id);

CREATE INDEX idx_vehicle_type_make_id ON public.vehicle_type USING btree (make_id);

CREATE INDEX idx_vehicle_variable_value_variable_id ON public.vehicle_variable_value USING btree (variable_id);

CREATE UNIQUE INDEX ux_make_manufacturer_name_lower ON public.make USING btree (manufacturer_id, lower((name)::text)) WHERE (manufacturer_id IS NOT NULL);

CREATE UNIQUE INDEX ux_make_name_lower_no_manufacturer ON public.make USING btree (lower((name)::text)) WHERE (manufacturer_id IS NULL);

CREATE UNIQUE INDEX ux_manufacturer_name_lower ON public.manufacturer USING btree (lower((name)::text));

CREATE UNIQUE INDEX ux_model_make_name_lower ON public.model USING btree (make_id, lower((name)::text)) WHERE (make_id IS NOT NULL);

CREATE UNIQUE INDEX ux_model_name_lower_no_make ON public.model USING btree (lower((name)::text)) WHERE (make_id IS NULL);

CREATE UNIQUE INDEX ux_vehicle_type_make_name_lower ON public.vehicle_type USING btree (make_id, lower((vehicle_type_name)::text)) WHERE (make_id IS NOT NULL);

CREATE UNIQUE INDEX ux_vehicle_type_name_lower_no_make ON public.vehicle_type USING btree (lower((vehicle_type_name)::text)) WHERE (make_id IS NULL);

ALTER TABLE ONLY public.fitment_tags
    ADD CONSTRAINT fk_fitment_tags_hint FOREIGN KEY (hint_id) REFERENCES public.vehicle_applicability_hints(hint_id) ON DELETE CASCADE;

ALTER TABLE ONLY public.make
    ADD CONSTRAINT fk_make_manufacturer FOREIGN KEY (manufacturer_id) REFERENCES public.manufacturer(id);

ALTER TABLE ONLY public.model
    ADD CONSTRAINT fk_model_make FOREIGN KEY (make_id) REFERENCES public.make(id);

ALTER TABLE ONLY public.part_fitment_entity_vehicle_variable_values
    ADD CONSTRAINT fk_part_fitment_entity_vehicle_values_fitment FOREIGN KEY (part_fitment_entity_id) REFERENCES public.part_fitment_entity(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.part_fitment_entity_vehicle_variable_values
    ADD CONSTRAINT fk_part_fitment_entity_vehicle_values_value FOREIGN KEY (vehicle_variable_values_id) REFERENCES public.vehicle_variable_value(id);

ALTER TABLE ONLY public.part_fitment_entity
    ADD CONSTRAINT fk_part_fitment_make FOREIGN KEY (vehicle_make_id) REFERENCES public.make(id);

ALTER TABLE ONLY public.part_fitment_entity
    ADD CONSTRAINT fk_part_fitment_manufacturer FOREIGN KEY (vehicle_manufacturer_id) REFERENCES public.manufacturer(id);

ALTER TABLE ONLY public.part_fitment_entity
    ADD CONSTRAINT fk_part_fitment_model FOREIGN KEY (vehicle_model_id) REFERENCES public.model(id);

ALTER TABLE ONLY public.part_fitment_entity
    ADD CONSTRAINT fk_part_fitment_vehicle_type FOREIGN KEY (vehicle_type_id) REFERENCES public.vehicle_type(id);

ALTER TABLE ONLY public.vehicle_type
    ADD CONSTRAINT fk_vehicle_type_make FOREIGN KEY (make_id) REFERENCES public.make(id);

ALTER TABLE ONLY public.vehicle_variable_value
    ADD CONSTRAINT fk_vehicle_variable_value_variable FOREIGN KEY (variable_id) REFERENCES public.vehicle_variable(id);
